<script setup lang="ts">
import {ref,watch,nextTick} from 'vue'
import type { Slide,Theme,Proposal } from '@/types/aippt'
import type {FlexContainer} from '../render/flexLayout'
import {cloneJson} from '../render/clone'
import SlideStage from './SlideStage.vue'
const props=defineProps<{slide:Slide;theme:Theme;disabled?:boolean;canApply:boolean;request:()=>Promise<Proposal>;apply:(proposal:Proposal,candidate:string)=>Promise<void>;restore:(tree:FlexContainer)=>Promise<void>}>()
type Candidate=NonNullable<Proposal['candidates']>[number]
const entries=ref<{proposal:Proposal;candidate:Candidate;key:string}[]>([]),originalTree=ref<FlexContainer|null>(null),undoTree=ref<FlexContainer|null>(null),appliedKey=ref(''),busy=ref(false),error=ref('');let generation=0
watch(()=>props.slide.id,()=>{generation++;entries.value=[];originalTree.value=null;undoTree.value=null;appliedKey.value='';busy.value=false;error.value=''})
async function propose(more=false){const own=++generation;busy.value=true;error.value='';if(!more){entries.value=[];originalTree.value=props.slide.layout_tree?cloneJson(props.slide.layout_tree):null;undoTree.value=null;appliedKey.value=''}try{const result=await props.request();if(own!==generation)return;for(const candidate of result.candidates||[]){const existing=entries.value.find(e=>JSON.stringify(e.candidate.layout_tree)===JSON.stringify(candidate.layout_tree));const entry={proposal:result,candidate,key:(result.proposal_id||result.id||String(own))+':'+candidate.id};if(existing)Object.assign(existing,entry);else entries.value.push(entry)}}catch(e:any){if(own===generation)error.value=e.message}finally{if(own===generation)busy.value=false}}
async function apply(entry:typeof entries.value[number]){if(entry.proposal.revision!==props.slide.revision){error.value='此轮候选已过期，请显示更多以生成当前版本候选';return}const own=generation;busy.value=true;try{const before=props.slide.layout_tree?cloneJson(props.slide.layout_tree):null;await props.apply(entry.proposal,entry.candidate.id);await nextTick();if(own!==generation)return;entry.proposal.revision=props.slide.revision;undoTree.value=before;appliedKey.value=entry.key;error.value=''}catch(e:any){if(own===generation)error.value=e.message}finally{if(own===generation)busy.value=false}}
async function restore(tree:FlexContainer){const own=generation;busy.value=true;try{await props.restore(cloneJson(tree));if(own!==generation)return;undoTree.value=null;appliedKey.value='';error.value=''}catch(e:any){if(own===generation)error.value=e.message}finally{if(own===generation)busy.value=false}}
</script>
<template><section><h4>换一种排布</h4><p>文字、图片与手工保护保持，候选预览不会修改正式页面。</p><el-button v-hasPermi="['aippt:ai:edit']" :loading="busy" :disabled="disabled||slide.layout_mode!=='flex'" @click="propose()">生成布局候选</el-button><el-alert v-if="error" type="error" :title="error"/><article v-if="originalTree" class="layout-candidate"><h5>原排布</h5><SlideStage :slide="{...slide,layout_tree:originalTree}" :theme="theme"/><el-button :disabled="disabled||!canApply||busy" @click="restore(originalTree)">恢复原排布</el-button><el-button v-if="undoTree" :disabled="disabled||!canApply||busy" @click="restore(undoTree)">撤销上次布局采纳</el-button></article><article v-for="(entry,i) in entries" :key="entry.key" class="layout-candidate"><h5>候选{{i+1}} <span v-if="appliedKey===entry.key">· 已应用</span></h5><SlideStage :slide="{...slide,layout_tree:entry.candidate.layout_tree}" :theme="theme"/><p v-if="entry.proposal.revision!==slide.revision">此轮候选已过期，生成当前版本候选后再应用。</p><el-button :disabled="disabled||!canApply||busy||entry.proposal.revision!==slide.revision" type="primary" @click="apply(entry)">应用此排布</el-button></article><el-button v-if="originalTree" :loading="busy" :disabled="disabled" @click="propose(true)">显示更多</el-button><el-button v-if="originalTree" :disabled="busy" @click="entries=[];originalTree=null;undoTree=null">放弃候选</el-button></section></template>
<style scoped>p{color:#606266;line-height:1.5}.layout-candidate{padding:12px 0;border-bottom:1px solid #ebeef5}.layout-candidate .el-button{margin-top:12px}</style>
